      "romaji": "yaa, genki?"
    },
    {
      "speaker": "B",
      "text": "うん、元気だよ。そっちは？",
      "english": "Yeah, I'm good. How about you?",
      "pinyin": "yùn, genki dǎ. zǒng cǐ shì?",
      "romaji": "un, genki da yo. socchi wa?"
    },
    {
      "speaker": "A",
      "text": "元気だよ。今日、何する？",
      "english": "I'm good. What are you doing today?",
      "pinyin": "genki dǎ. jīntiān, shénme zuò?",
      "romaji": "genki da yo. kyou, nani suru?"
    },
    {
      "speaker": "B",
      "text": "うーん、特に何も。君は？",
      "english": "Hmm, nothing in particular. You?",
      "pinyin": "ūnn, tèbié shénme dōu méiyǒu. jūn shì?",
      "romaji": "uun, toku ni nani mo. kimi wa?"
    },
    {
      "speaker": "A",
      "text": "昨日、また家に行こうかと思ったんだけど。",
      "english": "I was thinking we could go to my place again yesterday.",
      "intendedTargetIds": [
        81,
        80
      ],
      "pinyin": "zuótiān, zài cì jiā qù ba xiǎng dào le.",
      "romaji": "kinou, mata ie ni ikou ka to omotta n dakedo."
    },
    {
      "speaker": "B",
      "text": "いいね。行こう。",
      "english": "Sounds good. Let's go.",
      "pinyin": "hǎo ne. qù ba.",
      "romaji": "ii ne. ikou."
    },
    {
      "speaker": "A",
      "text": "ごめん、ちょっと遅くなった。",
      "english": "Sorry, I'm a little late.",
      "intendedTargetIds": [
        87
      ],
      "pinyin": "zuì kuí, diǎnr chī le.",
      "romaji": "gomen, chotto osoku natta."
    },
    {
      "speaker": "B",
      "text": "大丈夫だよ。もう着いたよ。",
      "english": "It's okay. I've already arrived.",
      "pinyin": "dà zhàngfū dǎ. yǐjīng dào le.",
      "romaji": "daijoubu da yo. mou tsuita yo."
    }
  ],
  "sceneId": "LS1",
  "setting": "A street corner where two friends meet"
}

